#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

TOTAL_STAGES=6

# The prompts need a keyboard: `!` in Claude Code, a pipe or CI gives none, and the first read would die silently.
[[ -t 0 ]] || { echo "Run this in a real terminal (not through '!' or a pipe): mise run agent:setup" >&2; exit 1; }
# Secrets are kept out of the tracked .env; .sandcastle/.gitignore ignores this one.
ENV_FILE=.sandcastle/.env

REPO=$(git config --get remote.origin.url | sed -E 's#^(git@github.com:|https://github.com/)##; s#\.git$##')

banner "Nightly Sandcastle setup for $REPO"

stage "Check the GitHub CLI"
say "The wizard sets repo secrets, labels and issues with gh, so it must be signed in to $REPO."
if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
  say "gh is installed and signed in."
else
  warn "gh is missing or not signed in. Install it (https://cli.github.com), run: gh auth login"
  warn "Without it the wizard cannot set secrets or file issues; it will list what to do by hand."
fi
pause "Continue?"

stage "Claude: OAuth token for the agent"
say "The agent signs in with a long-lived token from your Claude subscription, not an API key."
step "In a terminal on your own machine, run:  claude setup-token"
step "Copy the token it prints (it starts sk-ant-oat)."
ask_secret CLAUDE_CODE_OAUTH_TOKEN "Paste the OAuth token:"
write_env CLAUDE_CODE_OAUTH_TOKEN "$CLAUDE_CODE_OAUTH_TOKEN"
set_secret CLAUDE_CODE_OAUTH_TOKEN "$CLAUDE_CODE_OAUTH_TOKEN"   # improve.yml and implement.yml read it

stage "GitHub: personal access token for pushing and opening PRs"
say "A PAT, not the built-in token, so that check.yml runs on the PRs the agent opens."
open_url "https://github.com/settings/personal-access-tokens/new"
step "Token name: sandcastle-agent. Expiration: your choice (90 days is reasonable)."
step "Repository access: Only select repositories > $REPO."
step "Repository permissions: Contents = Read and write; Pull requests = Read and write."
step "Leave Workflows, Administration and everything else at No access."
step "Generate the token and copy it (it starts github_pat_)."
ask_secret AGENT_PAT "Paste the token:"
write_env AGENT_PAT "$AGENT_PAT"
set_secret AGENT_PAT "$AGENT_PAT"   # implement.yml pushes and opens the PR with it

stage "Create the labels"
say "The workflows move issues between these labels; they must exist first."
if confirm "Create the agent:*, strength:*, door:* and priority:* labels, and request, in $REPO?"; then
  for spec in \
    "agent:candidate|Architecture candidate filed by the nightly run|0e8a16" \
    "agent:implement|Add to start the implement workflow|1d76db" \
    "agent:spec|Add to expand a short note into a full spec|c5def5" \
    "agent:in-progress|The implement workflow is running|fbca04" \
    "agent:pr-open|The implement workflow opened a PR for this issue|0e8a16" \
    "agent:blocked|The implement workflow could not finish|d93f0b" \
    "agent:recovered|The one recovery attempt for this issue has been used|fef2c0" \
    "agent:recovered-ok|The recovery attempt succeeded|c2e0c6" \
    "request|Filed by a human from the issue template; outranks the nightly scan|0075ca" \
    "priority:high|Jump the implement queue|b60205" \
    "strength:strong|Candidate strength: strong|5319e7" \
    "strength:explore|Candidate strength: worth exploring|5319e7" \
    "door:one-way|PR review: hard to reverse|b60205" \
    "door:two-way|PR review: easy to reverse|0e8a16"; do
    IFS='|' read -r name desc color <<<"$spec"
    if gh label create "$name" --description "$desc" --color "$color" --force >/dev/null 2>&1; then
      say "✓ $name"
    else
      SKIPPED+=("label $name (gh label create \"$name\" --force)")
      warn "could not create $name"
    fi
  done
else
  SKIPPED+=("create the agent:*, strength:* and door:* labels")
fi

stage "Move the old backlog into issues"
say "docs/architecture-candidates.md holds numbered candidates. Each becomes an agent:candidate issue."
say "Entries already filed (same title) are skipped, so this is safe to re-run."
note "The audit section at the end of that file is not migrated; file those by hand if you want them."
if confirm "File the numbered candidates as issues in $REPO?"; then
  existing=$(gh issue list --state all --label agent:candidate --limit 1000 --json title --jq '.[].title' 2>/dev/null || true)
  tmpdir=$(mktemp -d)
  awk -v dir="$tmpdir" '
    /^## [0-9]+\. / { n++; file = sprintf("%s/%02d.md", dir, n) }
    /^## Audit/ { file = "" }
    file != "" { print > file }
  ' docs/architecture-candidates.md
  for f in "$tmpdir"/*.md; do
    heading=$(head -n1 "$f" | sed -E 's/^## [0-9]+\. //')
    strength=$(printf '%s' "$heading" | sed -nE 's/.*\((strong|worth exploring|speculative)\)$/\1/p')
    title=$(printf '%s' "$heading" | sed -E 's/ \((strong|worth exploring|speculative)\)$//')
    case "$strength" in
      strong) label=strength:strong ;;
      "worth exploring") label=strength:explore ;;
      *) note "skipping '$title' (${strength:-no strength}): not worth an issue"; continue ;;
    esac
    if grep -qxF "$title" <<<"$existing"; then note "already filed: $title"; continue; fi
    body=$(mktemp)
    { tail -n +2 "$f"; printf '\n---\nMigrated from docs/architecture-candidates.md. This is a backlog note, not a full spec: edit it into one (Problem, Files, Proposal, Benefits, Tests, Acceptance criteria, Out of scope) before adding `agent:implement`.\n'; } > "$body"
    if gh issue create --title "$title" --body-file "$body" --label agent:candidate --label "$label" >/dev/null 2>&1; then
      say "✓ $title"
    else
      SKIPPED+=("issue: $title")
      warn "could not file: $title"
    fi
  done
  note "Afterwards, delete docs/architecture-candidates.md in a commit and repoint the two specs that cite it."
else
  SKIPPED+=("migrate docs/architecture-candidates.md into agent:candidate issues")
fi

stage "First dry run"
say "The workflows only exist on the default branch, so merge the PR that adds them before this stage."
if confirm "Have the workflows been merged to main?"; then
  if gh workflow run improve.yml --ref main -f dry_run=true >/dev/null 2>&1; then
    say "✓ started improve (dry run)"
  else
    SKIPPED+=("run: gh workflow run improve.yml --ref main -f dry_run=true")
    warn "could not start it from here"
  fi
  open_url "https://github.com/$REPO/actions/workflows/improve.yml"
  step "When it finishes, open the run and read the Summary tab: that is what it would file."
  step "If it looks good, uncomment the two schedule lines in .github/workflows/improve.yml and merge."
  step "To try an implementation, add the agent:implement label to one of the issues."
  pause "Done?"
else
  SKIPPED+=("after merging: gh workflow run improve.yml --ref main -f dry_run=true")
fi

finish
}

run_wizard "$@"; exit
